# Practical Generators 💡

## Reading Large Files

```python
def read_large_file(filepath):
    with open(filepath, 'r') as file:
        for line in file:
            yield line.strip()

# Process line by line - never loads entire file!
for line in read_large_file('huge_file.txt'):
    process(line)
```

## Infinite Sequences

```python
def infinite_counter():
    num = 0
    while True:
        yield num
        num += 1

counter = infinite_counter()
print(next(counter))  # 0
print(next(counter))  # 1
# Can go forever!
```

## Pipeline Processing

```python
def numbers():
    for i in range(10):
        yield i

def squared(nums):
    for n in nums:
        yield n ** 2

def evens_only(nums):
    for n in nums:
        if n % 2 == 0:
            yield n

# Chain generators
pipeline = evens_only(squared(numbers()))
print(list(pipeline))  # [0, 4, 16, 36, 64]
```

# Real-World Decorators 🌟

## Timing Decorator

```python
import time

def timer(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} took {end-start:.4f}s")
        return result
    return wrapper

@timer
def slow_function():
    time.sleep(1)
    return "Done!"

slow_function()  # slow_function took 1.0012s
```

## Caching Decorator

```python
def memoize(func):
    cache = {}
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

@memoize
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(100))  # Instant! (without memo: very slow)
```

## functools.wraps (Best Practice)

```python
from functools import wraps

def my_decorator(func):
    @wraps(func)  # Preserves function metadata
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper
```
